method.body:
function Constructor(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var jCurObjDiv = $(oCurObj.div);
    // Add 'parent'(the component from which the inheritance was based) classname
    // See also CLObject constructor
    jCurObjDiv.addClass("clo-v_q_0002");
    var sQuestionId = argobj.pid;
    oCurObj.data =
    {
        aTargets: [],
        bAcceptBtnHasState: (oCurObj.jxParams.children("accept_object_based").text()!="yes"),
        bCreated: false,
        bCredit: (oCurObj.jxParams.children("q_scored").text()=="yes"),
        bDisplayQText: (oCurObj.jxParams.find("display_question_text").text()=="yes"),
        bDisplayInstruction: (oCurObj.jxParams.find("display_instruction").text()=="yes"),
        bNoMoreAttempts: false,
        bShowCorrect: (oCurObj.jxParams.children("final_action").text()!="none"),
        bFeedback: (oCurObj.jxParams.children("q_fb_switch").text()=="yes"),
        bFeedbackTimer: (oCurObj.jxParams.children("q_fb_timerswitch").text()=="yes"),
        bFeedbackCorrect: (oCurObj.jxParams.children("q_display_fb_correct").text()=="yes"),
        bFeedbackIncorrect: (oCurObj.jxParams.children("q_fb_incorrect_type").text()!="none"),
        bReplace: (oCurObj.jxParams.children("if_busy").text()!="leave"),
        bUseBtnState: (oCurObj.jxParams.children("accept_object_based").text()!="yes"),

        iHideFBIn: +oCurObj.jxParams.children("q_fb_timer").text(),
        iFBTimer: 0,
        iDisplayTimer: 0,
        iTotalElems: oCurObj.jxParams.find("q_variants > item > bullets > item").length,

        jxObjectives: oCurObj.jxParams.find("q_scoreboards > item"),
        jxVars: oCurObj.jxParams.find("q_variants > item"),

        nBaseScore: +oCurObj.jxParams.children("q_weight").text(),

        oBullets: {},

        sFeedbackIncorrect: oCurObj.jxParams.children("q_fb_incorrect_type").text(),
        sMode: "init",
        sType: "otm",
        sDisplayOrder: oCurObj.jxParams.children("display_order").text(),
        sScoringType: oCurObj.jxParams.children("q_scoring_type").text(),
        sSoundSuccess: oCurObj.jxParams.children("sound_success").text(),
        sSoundFailure: oCurObj.jxParams.children("sound_failure").text(),
        sSoundClick: oCurObj.jxParams.children("sound_click").text(),
        sSoundOver: oCurObj.jxParams.children("sound_over").text(),
        sQTextId: oCurObj.jxParams.children("q_text_obj").text(),
        sInstrId: oCurObj.jxParams.children("q_instruction_obj").text(),
        sSnap: oCurObj.jxParams.children("snap").text(),
        sOnFinish: oCurObj.jxParams.children("q_on_finish").text(),
        sSubmitType: oCurObj.jxParams.children("q_submit_type").text()
    };
    if(oCurObj.data.sSoundClick!="none")
    {
        oCurObj.data.jAudioClick = CL.Sound.Append({ oContainer: jAudioContainer, sId: argobj.pid + "_AUDIO1", sType: oCurObj.data.sSoundClick, sFile: oCurObj.jxParams.children("sound_click_file_custom").text() });
    }
    if(oCurObj.data.sSoundOver!="none")
    {
        oCurObj.data.jAudioOver = CL.Sound.Append({ oContainer: jAudioContainer, sId: argobj.pid + "_AUDIO2", sType: oCurObj.data.sSoundOver, sFile: oCurObj.jxParams.children("sound_over_file_custom").text() });
    }
    if(oCurObj.data.sSoundSuccess!="none")
    {
        oCurObj.data.jAudioSuccess = CL.Sound.Append({ oContainer: jAudioContainer, sId: argobj.pid + "_AUDIO3", sType: oCurObj.data.sSoundSuccess, sFile: oCurObj.jxParams.children("sound_success_file_custom").text() });
    }
    if(oCurObj.data.sSoundFailure!="none")
    {
        oCurObj.data.jAudioFailure = CL.Sound.Append({ oContainer: jAudioContainer, sId: argobj.pid + "_AUDIO4", sType: oCurObj.data.sSoundFailure, sFile: oCurObj.jxParams.children("sound_failure_file_custom").text() });
    }
    var jxVar;
    var jxBullets;
    var jxBullet;
    var sTargetId;
    var sBulletId;
    var jxObjectNode;
    var jxGroup;
    var aTargetIds = [];
    var iCnt;
    var aStraightOrder = [];
    var sBulletCode;
    for(var i=1; i<=oCurObj.data.jxVars.length; i++)
    {
        jxVar = $(oCurObj.data.jxVars[i-1]);
        sTargetId = jxVar.children("q_var_target").text();
        if(sTargetId=="")
        {
            oCurObj.data.aTargets.push("");
        }
        else
        {
            jxObjectNode = CL.jxModule.find("object[id='" + sTargetId + "']");
            if(jxObjectNode.length!=0)
            {
                oCurObj.data.aTargets.push(sTargetId);
            }
            else
            {
                jxGroup = CL.jxGroups.find("group[id='" + sTargetId + "']");
                if(jxGroup.length!=0)
                {
                    aTargetIds = [];
                    jxGroup.children("ref").each(function ()
                    {
                        aTargetIds.push($(this).attr("id"))
                    });
                    oCurObj.data.aTargets.push(aTargetIds.slice(0));
                }
                else
                {
                    oCurObj.data.aTargets.push("");
                }
            }
        }
        jxBullets = jxVar.find("bullets > item");
        iCnt = 1;
        for(var j=1; j<=jxBullets.length; j++)
        {
            jxBullet = $(jxBullets[j-1]);
            sBulletId = jxBullet.children("q_var_bullet").text();
            if(sBulletId=="")
            {
                continue;
            }
            jxObjectNode = CL.jxModule.find("object[id='" + sBulletId + "']");
            if(jxObjectNode.length!=0)
            {
                sBulletCode = "t" + i + "b" + iCnt;
                oCurObj.data.oBullets[sBulletCode] = { sId: sBulletId, iT: i, iB: j };
                aStraightOrder.push(sBulletCode);
                iCnt++;
            }
            else
            {
                jxGroup = CL.jxGroups.find("group[id='" + sBulletId + "']");
                if(jxGroup.length!=0)
                {
                    aTargetIds = [];
                    jxGroup.children("ref").each(function ()
                    {
                        aTargetIds.push($(this).attr("id"))
                    });
                    for(var k=0; k<aTargetIds.length; k++)
                    {
                        sBulletCode = "t" + i + "b" + iCnt;
                        oCurObj.data.oBullets[sBulletCode] = { sId: aTargetIds[k], iT: i, iB: j };
                        aStraightOrder.push(sBulletCode);
                        iCnt++;
                    }
                }
            }
        }
    }
    if(CLZ.oStore[sQuestionId]!=null)
    {
        switch(CLZ.oStore[sQuestionId].u)
        {
            case "c":
            {
                switch(oCurObj.jxParams.children("q_replay").text())
                {
                    case "none_alert":
                    {
                        alert(oCurObj.jxParams.children("q_browse_alert").text());
                        // no break
                    }
                    case "none_silent":
                    {
                        oCurObj.data.sMode = "browse";
                        oCurObj.data.bNoMoreAttempts = true;
                        break;
                    }
                    case "allow_alert":
                    {
                        alert(oCurObj.jxParams.children("q_secondrun_alert").text());
                        // no break
                    }
                    case "allow_silent":
                    {
                        CLZ.oStore[sQuestionId] = {};
                        CLZ.oStore[sQuestionId] = null;
                        if(oCurObj.data.bCredit)
                        {
                            for(var j=0; j<oCurObj.data.jxObjectives.length; j++)
                            {
                                CL.SCO.RemoveScoreFromObjective({ sId: $(oCurObj.data.jxObjectives[j]).children("q_board").text(), sSrcId: argobj.pid });
                            }
                        }
                        break;
                    }
                    case "allow_confirm":
                    {
                        if(confirm(oCurObj.jxParams.children("q_secondrun_confirm").text()))
                        {
                            CLZ.oStore[sQuestionId] = {};
                            CLZ.oStore[sQuestionId] = null;
                            if(oCurObj.data.bCredit)
                            {
                                for(var j=0; j<oCurObj.data.jxObjectives.length; j++)
                                {
                                    CL.SCO.RemoveScoreFromObjective({ sId: $(oCurObj.data.jxObjectives[j]).children("q_board").text(), sSrcId: argobj.pid });
                                }
                            }
                        }
                        else
                        {
                            oCurObj.data.sMode = "browse";
                            oCurObj.data.bNoMoreAttempts = true;
                        }
                        break;
                    }
                }
                break;
            }
            case "i":
            {
                switch(oCurObj.jxParams.children("q_continue").text())
                {
                    case "restart_alert":
                    {
                        alert(oCurObj.jxParams.children("q_restart_alert").text());
                        // no break
                    }
                    case "restart_silent":
                    {
                        CLZ.oStore[sQuestionId] = {};
                        CLZ.oStore[sQuestionId] = null;
                        if(oCurObj.data.bCredit)
                        {
                            for(var j=0; j<oCurObj.data.jxObjectives.length; j++)
                            {
                                CL.SCO.RemoveScoreFromObjective({ sId: $(oCurObj.data.jxObjectives[j]).children("q_board").text(), sSrcId: argobj.pid });
                            }
                        }
                        break;
                    }
                    case "restore_alert":
                    {
                        alert(oCurObj.jxParams.children("q_restore_alert").text());
                        // no break
                    }
                    case "restore_silent":
                    {
                        oCurObj.data.sMode = "continue";
                        break;
                    }
                    case "restore_confirm":
                    {
                        if(confirm(oCurObj.jxParams.children("q_restore_confirm").text()))
                        {
                            oCurObj.data.sMode = "continue";
                        }
                        else
                        {
                            CLZ.oStore[sQuestionId] = {};
                            CLZ.oStore[sQuestionId] = null;
                            if(oCurObj.data.bCredit)
                            {
                                for(var j=0; j<oCurObj.data.jxObjectives.length; j++)
                                {
                                    CL.SCO.RemoveScoreFromObjective({ sId: $(oCurObj.data.jxObjectives[j]).children("q_board").text(), sSrcId: argobj.pid });
                                }
                            }
                        }
                        break;
                    }
                }
                break;
            }
            default:
            {
                CLZ.oStore[sQuestionId] = {};
                CLZ.oStore[sQuestionId] = null;
                if(oCurObj.data.bCredit)
                {
                    for(var j=0; j<oCurObj.data.jxObjectives.length; j++)
                    {
                        CL.SCO.RemoveScoreFromObjective({ sId: $(oCurObj.data.jxObjectives[j]).children("q_board").text(), sSrcId: argobj.pid });
                    }
                }
                break;
            }
        }
    }
    switch(oCurObj.data.sMode)
    {
        case "init":
        {
            // create storage
            CLZ.oStore[sQuestionId] =
            {
                A:
                [
                    {
                        s: 0,
                        d: 0,
                        u: "i"
                    }
                ],
                O: [],
                P: [],
                R: [],
                s: (new Date()).valueOf(),
                y: CLD.CLTypeToAbbr[oCurObj.data.sType],
                u: "i"
            };
            if(oCurObj.data.bCredit)
            {
                CLZ.oStore[sQuestionId].J = [];
                oCurObj.data.jxObjectives.each(function () { CLZ.oStore[sQuestionId].J.push( $(this).children("q_board").text() ); });
            }
            for(var i=0; i<oCurObj.data.jxVars.length; i++)
            {
                CLZ.oStore[sQuestionId].P.push([]);
            }
            for(var sKey in oCurObj.data.oBullets)
            {
                CLZ.oStore[sQuestionId].P[ oCurObj.data.oBullets[sKey].iT - 1 ].push(sKey);
            }
            var aShuffled = [];
            for(var i=0; i<aStraightOrder.length; i++) aShuffled.push( CLTOOLS.Dice({ iMax: aStraightOrder.length, bIncludeMax: false, aUsed: aShuffled, iMaxTries: 1000 }) );
            for(var i=0; i<aShuffled.length; i++)
            {
                CLZ.oStore[sQuestionId].O.push( aStraightOrder[aShuffled[i]] );
            }
            for(var i=0; i<oCurObj.data.aTargets.length; i++)
            {
                if(typeof oCurObj.data.aTargets[i] == "string")
                {
                    CLZ.oStore[sQuestionId].R.push([]);
                }
                else
                {
                    var aDrops = [];
                    for(var j=0; j<oCurObj.data.aTargets[i].length;j++)
                    {
                        aDrops.push("");
                    }
                    CLZ.oStore[sQuestionId].R.push(aDrops.slice(0));
                }
            }
            var iMaxAttepmts = 1;
            if(oCurObj.data.sScoringType!="byvar")
            {
                if(oCurObj.jxParams.children("q_attempts_type").text()=="auto")
                {
                    iMaxAttepmts = oCurObj.data.jxVars.length - 1;
                }
                else
                {
                    iMaxAttepmts = +oCurObj.jxParams.children("q_attempts").text();
                }
            }
            for(var i=1; i<iMaxAttepmts; i++)
            {
                CLZ.oStore[sQuestionId].A.push({ u: "n" });
            }
            break;
        }
        case "browse":
        case "continue":
        {
            break;
        }
    }
    oCurObj.data.bCreated = true;
    CL.Event.Subscribe({ aList: [ { sId: argobj.pid, sEvtName: "EVENT_OBJECT_SHOW" } ] });
    return true;
}

function Validate(argobj)
{
    if(navigator.userAgent.toLowerCase().indexOf("courselab")==-1) return false;
    var oCurObj = CLO[argobj.pid];
    if(oCurObj==null) return false;
    var aWarnings = [];
    var aErrors = [];
    if(oCurObj.data.bDisplayQText)
    {
        if(oCurObj.data.sQTextId=="")
        {
            aWarnings.push({ sId: "qtext_empty" });
        }
        else if(CLO[oCurObj.data.sQTextId]==null && CL.jxGroups.find("group[id='" + oCurObj.data.sQTextId + "']").length==0)
        {
            aWarnings.push({ sId: "qtext_not_exist", aSub: [ oCurObj.data.sQTextId ] });
        }
    }
    if(oCurObj.data.bDisplayInstruction)
    {
        if(oCurObj.data.sInstrId=="")
        {
            aWarnings.push({ sId: "instr_empty" });
        }
        else if(CLO[oCurObj.data.sInstrId]==null && CL.jxGroups.find("group[id='" + oCurObj.data.sInstrId + "']").length==0)
        {
            aWarnings.push({ sId: "instr_not_exist", aSub: [ oCurObj.data.sInstrId ] });
        }
    }
    var jxVar;
    var sId;
    var aParams = [ "q_var_bullet" ];
    var jxBullet;
    var jxBullets;
    if(oCurObj.data.sOnFinish=="disabled") aParams.push("q_var_disabled");
    if(oCurObj.data.jxVars.length==0)
    {
        aErrors.push({ sId: "no_targets" });
    }
    else
    {
        for(var i=0; i<oCurObj.data.jxVars.length; i++)
        {
            if(oCurObj.data.aTargets[i]!="")
            {
                if(typeof oCurObj.data.aTargets[i] == "string")
                {
                    if(CLO[oCurObj.data.aTargets[i]]==null && CL.jxGroups.find("group[id='" + oCurObj.data.aTargets[i] + "']").length==0)
                    {
                        aErrors.push({ sId: "target_not_exists", aSub: [ i+1, oCurObj.data.aTargets[i] ] });
                    }
                }
                else if(typeof oCurObj.data.aTargets[i] == "object")
                {
                    for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                    {
                        if(CLO[oCurObj.data.aTargets[i][j]]==null)
                        {
                            aErrors.push({ sId: "target_not_found", aSub: [ i+1, oCurObj.data.aTargets[i][j] ] });
                        }
                    }
                }
            }
            else
            {
                aErrors.push({ sId: "target_is_empty", aSub: [ i+1 ] });
            }
            jxBullets = $(oCurObj.data.jxVars[i]).find("bullets > item");
            if(jxBullets.length==0)
            {
                aWarnings.push({ sId: "no_bullets", aSub: [ i+1 ] });
            }
            else
            {
                for(var j=0; j<jxBullets.length; j++)
                {
                    jxBullet = $(jxBullets[j]);
                    for(var k=0; k<aParams.length; k++)
                    {
                        if(jxBullet.children("var_object_based").text()=="yes")
                        {
                            sId = jxBullet.children(aParams[k]).text();
                            if(sId=="")
                            {
                                aErrors.push({ sId: "bullet_is_empty_" + k, aSub: [ i+1, j+1 ] });
                            }
                            else if(CLO[sId]==null)
                            {
                                aErrors.push({ sId: "bullet_not_exists", aSub: [ i+1, j+1, sId ] });
                            }
                        }
                        else
                        {
                            sId = jxBullet.children(aParams[0]).text();
                            if(k==0)
                            {
                                if(sId=="")
                                {
                                    aErrors.push({ sId: "bullet_is_empty_" + k, aSub: [ i+1, j+1 ] });
                                    break;
                                }
                                if(CLO[sId]==null)
                                {
                                    aErrors.push({ sId: "bullet_not_exists", aSub: [ i+1, j+1, sId ] });
                                    break;
                                }
                            }
                            else if(k==1)
                            {
                                if(CLO[sId].oStates["disabled"]==null)
                                {
                                    aErrors.push({ sId: "bullet_state_disabled_not_defined", aSub: [ i+1, j+1, sId ] });
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if(oCurObj.data.sSubmitType=="button")
    {
        var sBtnIdle = oCurObj.jxParams.children("q_submit_idle").text();
        if(sBtnIdle!="")
        {
            if(CLO[sBtnIdle]==null)
            {
                aErrors.push({ sId: "btn_not_exists", aSub: [ sBtnIdle ] });
            }
            else
            {
                if(!oCurObj.data.bAcceptBtnHasState)
                {
                    var sBtnOver = oCurObj.jxParams.children("q_submit_over").text();
                    var sBtnDisabled = oCurObj.jxParams.children("q_submit_disabled").text();
                    if(sBtnOver!="")
                    {
                        if(CLO[sBtnOver]==null)
                        {
                            aErrors.push({ sId: "btn_hover_not_exists", aSub: [ sBtnOver ] });
                        }
                    }
                    else
                    {
                        aWarnings.push({ sId: "no_btn_hover" });
                    }
                    if(sBtnDisabled!="")
                    {
                        if(CLO[sBtnDisabled]==null)
                        {
                            aErrors.push({ sId: "btn_disabled_not_exists", aSub: [ sBtnDisabled ] });
                        }
                    }
                    else
                    {
                        aWarnings.push({ sId: "no_btn_disabled" });
                    }
                }
                else
                {
                    if(CLO[sBtnIdle].oStates["highlighted"]==null)
                    {
                        aWarnings.push({ sId: "no_btn_state_highlighted" });
                    }
                    if(CLO[sBtnIdle].oStates["disabled"]==null)
                    {
                        aWarnings.push({ sId: "no_btn_state_disabled" });
                    }
                }
            }
        }
        else
        {
            aErrors.push({ sId: "btn_empty" });
        }
    }
    if(oCurObj.jxParams.children("q_scored").text()=="yes")
    {
        if(oCurObj.jxParams.find("q_scoreboards:first > item > q_board").length==0)
        {
            aWarnings.push({ sId: "no_objectives" });
        }
    }
    switch(oCurObj.jxParams.children("final_action").text())
    {
        case "mark":
        case "replace":
        {
            if(oCurObj.data.jxVars.length!=0)
            {
                var sIncId;
                var sCorId;
                for(var i=0; i<oCurObj.data.jxVars.length; i++)
                {
                    jxVar = $(oCurObj.data.jxVars[i]);
                    jxBullets = jxVar.find("bullets > item");
                    for(var j=0; j<jxBullets.length; j++)
                    {
                        jxBullet = $(jxBullets[j]);
                        sId = jxBullet.children("q_var_bullet").text();
                        if(sId!="")
                        {
                            if(jxBullet.children("var_object_based").text()=="yes")
                            {
                                sCorId = jxBullet.children("q_var_correct").text();
                                if(sCorId=="")
                                {
                                    aErrors.push({ sId: "bullet_correct_empty", aSub: [ i+1, j+1 ] });
                                }
                                else if(CLO[sCorId]==null && CL.jxGroups.find("group[id='" + sCorId + "']").length==0)
                                {
                                    aErrors.push({ sId: "bullet_correct_not_exists", aSub: [ i+1, j+1, sCorId ] });
                                }
                                sIncId = jxBullet.children("q_var_error").text();
                                if(sIncId=="")
                                {
                                    aErrors.push({ sId: "bullet_incorrect_empty", aSub: [ i+1, j+1 ] });
                                }
                                else if(CLO[sIncId]==null && CL.jxGroups.find("group[id='" + sIncId + "']").length==0)
                                {
                                    aErrors.push({ sId: "bullet_incorrect_not_exists", aSub: [ i+1, j+1, sIncId ] });
                                }
                            }
                            else
                            {
                                if(CLO[sId].oStates["correct"]==null)
                                {
                                    aErrors.push({ sId: "bullet_no_correct_state", aSub: [ i+1, j+1, sId ] });
                                }
                                if(CLO[sId].oStates["incorrect"]==null)
                                {
                                    aErrors.push({ sId: "bullet_no_incorrect_state", aSub: [ i+1, j+1, sId ] });
                                }
                            }
                        }
                    }
                }
            }
        } // break omitted intentionally
        case "correct":
        {
            var sFinalObjId = oCurObj.jxParams.children("final_obj").text();
            if(sFinalObjId=="")
            {
                aWarnings.push({ sId: "no_final_obj" });
            }
            else if(CLO[sFinalObjId]==null && CL.jxGroups.find("group[id='" + sFinalObjId + "']").length==0)
            {
                aWarnings.push({ sId: "final_obj_not_exists", aSub: [ sFinalObjId ] });
            }
            break;
        }
    }
    if(oCurObj.jxParams.children("q_fb_switch").text()=="yes")
    {
        if(oCurObj.jxParams.children("q_display_fb_correct").text()=="yes")
        {
            sId = oCurObj.jxParams.children("q_fb_correct").text();
            if(sId=="")
            {
                aErrors.push({ sId: "fb_correct_empty", aSub: [ i+1, j+1 ] });
            }
            else if(CLO[sId]==null && CL.jxGroups.find("group[id='" + sId + "']").length==0)
            {
                aErrors.push({ sId: "fb_correct_not_exists", aSub: [ sId ] });
            }
        }
        switch(oCurObj.jxParams.children("q_fb_incorrect_type").text())
        {
            case "common":
            {
                sId = oCurObj.jxParams.children("q_fb_incorrect_common").text();
                if(sId=="")
                {
                    aErrors.push({ sId: "fb_incorrect_empty", aSub: [ i+1, j+1 ] });
                }
                else if(CLO[sId]==null && CL.jxGroups.find("group[id='" + sId + "']").length==0)
                {
                    aErrors.push({ sId: "fb_incorrect_not_exists", aSub: [ sId ] });
                }
                break;
            }
            case "byatt":
            {
                var jxFBItems = jxVar.find("q_fb_incorrect_by_attempt:first > item");
                if(jxFBItems.length==0)
                {
                    aErrors.push({ sId: "fb_incorrect_list_empty", aSub: [ sId ] });
                }
                else
                {
                    for(var j=0; j<jxFBItems.length; j++)
                    {
                        sId = $(jxFBItems[j]).children("q_fb_incorrect_by_att").text();
                        if(sId=="")
                        {
                            aErrors.push({ sId: "fb_incorrect_by_att_empty", aSub: [ j+1 ] });
                        }
                        else if(CLO[sId]==null && CL.jxGroups.find("group[id='" + sId + "']").length==0)
                        {
                            aErrors.push({ sId: "fb_incorrect_by_att_not_exists", aSub: [ j+1, sId ] });
                        }
                    }
                }
                break;
            }
        }
    }
    if(aErrors.length!=0 || aWarnings.length!=0)
    {
        var jMsg = $(document.createElement("div")).addClass("cl-object-debug-msg").appendTo(CL.oBoard);
        var sTxt = "<h3>" + oCurObj.jxParams.children("hidden_msg_header").text() + " " + oCurObj.jxParams.children("hidden.object").text() + " " + argobj.pid + "</h3>";
        var sTmp;
        var aParts;
        if(aErrors.length!=0)
        {
            sTxt += "<h4>" + oCurObj.jxParams.children("hidden_msg_errors").text() + "</h4><ul>";
            for(var i=0; i<aErrors.length; i++)
            {
                sTmp = oCurObj.jxParams.children("hidden_msg_error_" + aErrors[i].sId).text();
                if(sTmp!="")
                {
                    if(aErrors[i].aSub!=null)
                    {
                        for(var j=0; j<aErrors[i].aSub.length; j++)
                        {
                            aParts = sTmp.split("{{" + j + "}}");
                            sTmp = aParts.join(aErrors[i].aSub[j]);
                        }
                    }
                    sTxt += "<li>" + sTmp + "</li>";
                }
            }
            sTxt += "</ul>";
        }
        if(aWarnings.length!=0)
        {
            sTxt += "<h4>" + oCurObj.jxParams.children("hidden_msg_warnings").text() + "</h4><ul>";
            for(var i=0; i<aWarnings.length; i++)
            {
                sTmp = oCurObj.jxParams.children("hidden_msg_warning_" + aWarnings[i].sId).text();
                if(sTmp!="")
                {
                    if(aWarnings[i].aSub!=null)
                    {
                        for(var j=0; j<aWarnings[i].aSub.length; j++)
                        {
                            aParts = sTmp.split("{{" + j + "}}");
                            sTmp = aParts.join(aWarnings[i].aSub[j]);
                        }
                    }
                    sTxt += "<li>" + sTmp + "</li>";
                }
            }
            sTxt += "</ul>";
        }
        jMsg.html(sTxt);
        $(document.createElement("div")).addClass("cl-object-debug-msg-close").html("&#215;").on("click", function () { jMsg.hide(); }).appendTo(jMsg);
    }
    return true;
}

function Cleanup(argobj)
{
    var oCurObj = CLO[argobj.pid];
    if(oCurObj==null) return false;
    if(oCurObj.data.sSubmitType=="button")
    {
        var sBtnIdle = oCurObj.jxParams.children("q_submit_idle").text();
        if(sBtnIdle!="")
        {
            if(CLO[sBtnIdle]!=null)
            {
                if(oCurObj.data.bAcceptBtnHasState)
                {
                    if(CLO[sBtnIdle].oStates["selected"]!=null)
                    {
                        CLO[sBtnIdle].oStates["selected"].div.remove();
                        delete CLO[sBtnIdle].oStates["selected"];
                    }
                }
            }
        }
    }
    return true;
}

function HandleEvt(argobj)
{
    var oCurObj = CLO[argobj.pid];
    if(oCurObj==null) return false;
    switch(argobj.evt)
    {
        case "EVENT_OBJECT_SHOW":
        {
            if(!oCurObj.data.bCreated) return false;
            oCurObj.CallMethod({ sMethod: "Cleanup" });
            if(oCurObj.jxParams.children("display_debug_msg").text()=="yes")
            {
                oCurObj.CallMethod({ sMethod: "Validate" });
            }
            oCurObj.CallMethod({ sMethod: "Display" });
            break;
        }
    }
    return true;
}

function CheckInit(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var sTargetId;
    var nCenterX = 0;
    var nCenterY = 0;
    for(var sKey in oCurObj.data.oBullets)
    {
        nCenterX = CLO[ oCurObj.data.oBullets[sKey].sId ].current.x + 0.5*CLO[ oCurObj.data.oBullets[sKey].sId ].current.w;
        nCenterY = CLO[ oCurObj.data.oBullets[sKey].sId ].current.y + 0.5*CLO[ oCurObj.data.oBullets[sKey].sId ].current.h;
        for(var i=0; i<oCurObj.data.aTargets.length; i++)
        {
            if(typeof oCurObj.data.aTargets[i] == "string")
            {
                if( (nCenterX > CLO[ oCurObj.data.aTargets[i] ].current.x) && (nCenterX < (CLO[ oCurObj.data.aTargets[i] ].current.x + CLO[ oCurObj.data.aTargets[i] ].current.w)) && (nCenterY > CLO[ oCurObj.data.aTargets[i] ].current.y) && (nCenterY < (CLO[ oCurObj.data.aTargets[i] ].current.y + CLO[ oCurObj.data.aTargets[i] ].current.h)) )
                {
                    oCurObj.CallMethod({ sMethod: "Snap", oMethodArgs: { sDropId: oCurObj.data.aTargets[i], sDragId: oCurObj.data.oBullets[sKey].sId } });
                }
            }
            else if(typeof oCurObj.data.aTargets[i] == "object")
            {
                for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                {
                    if( (nCenterX > CLO[ oCurObj.data.aTargets[i][j] ].current.x) && (nCenterX < (CLO[ oCurObj.data.aTargets[i][j] ].current.x + CLO[ oCurObj.data.aTargets[i][j] ].current.w)) && (nCenterY > CLO[ oCurObj.data.aTargets[i][j] ].current.y) && (nCenterY < (CLO[ oCurObj.data.aTargets[i][j] ].current.y + CLO[ oCurObj.data.aTargets[i][j] ].current.h)) )
                    {
                        if(CLZ.oStore[sQuestionId].R[i][j]!=null && CLZ.oStore[sQuestionId].R[i][j]!="")
                        {
                            for(var k=0; k<oCurObj.data.aTargets[i].length; k++)
                            {
                                if(CLZ.oStore[sQuestionId].R[i][k]==null || CLZ.oStore[sQuestionId].R[i][k]=="")
                                {
                                    sTargetId = oCurObj.data.aTargets[i][k];
                                    break;
                                }
                            }
                        }
                        else
                        {
                            sTargetId = oCurObj.data.aTargets[i][j];
                        }
                        oCurObj.CallMethod({ sMethod: "Snap", oMethodArgs: { sDropId: sTargetId, sDragId: oCurObj.data.oBullets[sKey].sId } });
                    }
                }
            }
        }
    }
    return true;
}

function Place(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var jTarget;
    if(argobj.sTargetId!=null && argobj.sTargetId!="")
    {
        jTarget = $("#" + argobj.sTargetId);
    }
    else if(argobj.sTargetCode!=null && argobj.sTargetCode!="")
    {
        var oTarget = oCurObj.data.aTargets[+argobj.sTargetCode-1];
        if(typeof oTarget == "string")
        {
            jTarget = $("#" + oTarget);
        }
        else if(typeof oTarget == "object")
        {
            for(var i=0; i<oTarget.length; i++)
            {
                jTarget = $("#" + oTarget[i]);
                if(jTarget.attr("data-vq-placed")==null || jTarget.attr("data-vq-placed")=="")
                {
                    break;
                }
            }
        }
    }
    if(jTarget.length==0) return false;
    var iDropId = +jTarget.attr("data-vq-drop") - 1; // to address array
    var jxVar = $(oCurObj.data.jxVars[iDropId]);
    var iInterElem = +jxVar.children("interelem").text();
    var sPlaced = jTarget.attr("data-vq-placed");
    var aPlaced = (sPlaced==null || sPlaced=="") ? [] : sPlaced.split("|");
    if($.inArray(argobj.sBulletId, aPlaced)!=-1) return false;
    aPlaced.push(argobj.sBulletId);
    jTarget.attr({ "data-vq-placed": aPlaced.join("|") });
    if(oCurObj.data.sSnap=="none")
    {
        oCurObj.data.sSnap = "cm";
    }
    var oTarget =
    {
        iH: jTarget.height(),
        iL: jTarget.position().left/CLZ.nZoom,
        iT: jTarget.position().top/CLZ.nZoom,
        iW: jTarget.width()
    };
    var iLeft = oTarget.iL;
    var iTop = oTarget.iT;
    var iQty = aPlaced.length;
    var iTotalW = 0;
    var iTotalH = 0;
    var oElems = {};
    var jElem;
    for(var i=0; i<aPlaced.length; i++)
    {
        jElem = $("#" + aPlaced[i]);
        iTotalW += jElem.width();
        iTotalH += jElem.height();
    }
    iTotalW += (aPlaced.length-1)*iInterElem;
    iTotalH += (aPlaced.length-1)*iInterElem;
    var iNewL = (oCurObj.data.sSnap=="mc") ? (0.5*(oTarget.iW - iTotalW)) : ((oCurObj.data.sSnap=="mr") ? oTarget.iW : 0);
    var iFinalL = 0;
    for(var i=0; i<aPlaced.length; i++)
    {
        jElem = $("#" + aPlaced[i]);
        switch(oCurObj.data.sSnap)
        {
            case "ct":
            case "cm":
            case "cb":
            {
                iFinalL = 0.5*(oTarget.iW - jElem.width());
                break;
            }
            case "mc":
            case "ml":
            {
                iFinalL = iNewL;
                iNewL += jElem.width() + iInterElem;
                break;
            }
            case "mr":
            {
                iFinalL = iNewL - jElem.width();
                iNewL = iFinalL - iInterElem;
                break;
            }
        }
        jElem.css({ "left": ((iLeft + iFinalL)) + "px" });
    }
    var iNewT = (oCurObj.data.sSnap=="cm") ? (0.5*(oTarget.iH - iTotalH)) : ((oCurObj.data.sSnap=="cb") ? oTarget.iH : 0);
    var iFinalT = 0;
    for(var i=0; i<aPlaced.length; i++)
    {
        jElem = $("#" + aPlaced[i]);
        switch(oCurObj.data.sSnap)
        {
            case "ml":
            case "mc":
            case "mr":
            {
                iFinalT = 0.5*(oTarget.iH - jElem.height());
                break;
            }
            case "ct":
            case "cm":
            {
                iFinalT = iNewT;
                iNewT += jElem.height() + iInterElem;
                break;
            }
            case "cb":
            {
                iFinalT = iNewT - jElem.height();
                iNewT = iFinalT - iInterElem;
                break;
            }
        }
        jElem.css({ "top": ((iTop + iFinalT)) + "px" });
    }
    return true;
}

function Ready(argobj)
{
    var oCurObj = CLO[argobj.pid];
    if(oCurObj.data.bDisplayQText && oCurObj.data.sQTextId!="")
    {
        if(CLO[oCurObj.data.sQTextId]==null)
        {
            return false;
        }
    }
    if(oCurObj.data.bDisplayInstruction && oCurObj.data.sInstrId!="")
    {
        if(CLO[oCurObj.data.sInstrId]==null)
        {
            return false;
        }
    }
    var jxVar;
    var sId;
    var aParams = [ "q_var_bullet" ];
    var jxBullet;
    var jxBullets;
    if(oCurObj.data.sOnFinish=="disabled") aParams.push("q_var_disabled");
    for(var i=0; i<oCurObj.data.jxVars.length; i++)
    {
        if(oCurObj.data.aTargets[i]!="")
        {
            if(typeof oCurObj.data.aTargets[i] == "string")
            {
                if(CLO[oCurObj.data.aTargets[i]]==null)
                {
                    return false;
                }
            }
            else if(typeof oCurObj.data.aTargets[i] == "object")
            {
                for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                {
                    if(CLO[oCurObj.data.aTargets[i][j]]==null)
                    {
                        return false;
                    }
                }
            }
        }
        jxBullets = $(oCurObj.data.jxVars[i]).find("bullets > item");
        for(var j=0; j<jxBullets.length; j++)
        {
            jxBullet = $(jxBullets[j]);
            for(var k=0; k<aParams.length; k++)
            {
                sId = jxBullet.children(aParams[k]).text();
                if(sId!="")
                {
                    if(CLO[sId]==null) return false;
                }
            }
        }
    }
    // no need to check feedback
    if(oCurObj.data.sSubmitType=="button")
    {
        var sBtnIdle = oCurObj.jxParams.children("q_submit_idle").text();
        if(sBtnIdle!="")
        {
            if(CLO[sBtnIdle]==null)
            {
                return false;
            }
        }
        if(!oCurObj.data.bAcceptBtnHasState)
        {
            var sBtnOver = oCurObj.jxParams.children("q_submit_over").text();
            var sBtnDisabled = oCurObj.jxParams.children("q_submit_disabled").text();
            if(sBtnOver!="")
            {
                if(CLO[sBtnOver]==null)
                {
                    return false;
                }
            }
            if(sBtnDisabled!="")
            {
                if(CLO[sBtnDisabled]==null)
                {
                    return false;
                }
            }
        }
    }
    return true;
}

function Display(argobj)
{
    var oCurObj = CLO[argobj.pid];
    if(oCurObj==null) return false;
    var sQuestionId = argobj.pid;
    if(!oCurObj.CallMethod({ sMethod: "Ready" }))
    { // wait for all acting objects to be ready
        oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, 50);
        return false;
    }
    oCurObj.FireEvent({ sName: "onReady" });
    var sBulletId;
    var iDur;
    switch(oCurObj.data.sMode)
    {
        case "init":
        {
            if(oCurObj.data.bDisplayQText)
            {
                if(oCurObj.data.sQTextId!=null && oCurObj.data.sQTextId!="")
                {
                    if(CLO[oCurObj.data.sQTextId]!=null)
                    {
                        if(!$(CLO[oCurObj.data.sQTextId].div).is(":visible"))
                        {
                            CLO[oCurObj.data.sQTextId].Show();
                            if(CLO[oCurObj.data.sQTextId].tranin!=null)
                            {
                                var iDur = +CLO[oCurObj.data.sQTextId].tranin.duration;
                                if(iDur>0)
                                {
                                    oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur*1000);
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
            if(oCurObj.data.bDisplayInstruction)
            {
                if(oCurObj.data.sInstrId!=null && oCurObj.data.sInstrId!="")
                {
                    if(CLO[oCurObj.data.sInstrId]!=null)
                    {
                        if(!$(CLO[oCurObj.data.sInstrId].div).is(":visible"))
                        {
                            CLO[oCurObj.data.sInstrId].Show();
                            if(CLO[oCurObj.data.sInstrId].tranin!=null)
                            {
                                var iDur = +CLO[oCurObj.data.sInstrId].tranin.duration;
                                if(iDur>0)
                                {
                                    oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur*1000);
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
            var iDur;
            for(var i=0; i<oCurObj.data.aTargets.length; i++)
            {
                if(oCurObj.data.aTargets[i]=="")
                {
                    continue;
                }
                if(typeof oCurObj.data.aTargets[i] == "string")
                {
                    if($(CLO[ oCurObj.data.aTargets[i] ].div).is(":visible"))
                    {
                        continue;
                    }
                    CLO[ oCurObj.data.aTargets[i] ].Show();
                    if(CLO[ oCurObj.data.aTargets[i] ].tranin!=null)
                    {
                        iDur = +CLO[ oCurObj.data.aTargets[i] ].tranin.duration;
                        if(iDur>0)
                        {
                            oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur*1000);
                            return false;
                        }
                    }
                }
                else if(typeof oCurObj.data.aTargets[i] == "object")
                {
                    for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                    {
                        CLO[ oCurObj.data.aTargets[i][j] ].Show();
                        if(CLO[ oCurObj.data.aTargets[i][j] ].tranin!=null)
                        {
                            iDur = +CLO[ oCurObj.data.aTargets[i][j] ].tranin.duration;
                            if(iDur>0)
                            {
                                oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur*1000);
                                return false;
                            }
                        }
                    }
                }
            }
            if(CLZ.oStore[sQuestionId].O.length!=0)
            {
                if(oCurObj.data.sDisplayOrder=="seq")
                {
                    sBulletId = oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].O[0] ].sId;
                    if(!$(CLO[sBulletId].div).is(":visible"))
                    {
                        CLO[sBulletId].Show();
                        if(CLO[sBulletId].tranin!=null)
                        {
                            iDur = 1000*CLO[sBulletId].tranin.duration;
                            if(isNaN(iDur))
                            {
                                iDur = 100;
                            }
                            oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur);
                        }
                    }
                    if(CLZ.oStore[sQuestionId].O.length!=1)
                    {
                        for(var i=1; i<CLZ.oStore[sQuestionId].O.length; i++)
                        {
                            sBulletId = oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].O[i] ].sId;
                            if($(CLO[sBulletId].div).is(":visible"))
                            {
                                CLO[sBulletId].Hide({ bActionCall: true, bUseTransition: false });
                            }
                        }
                    }
                }
                else
                {
                    for(var i=0; i<CLZ.oStore[sQuestionId].O.length; i++)
                    {
                        sBulletId = oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].O[i] ].sId;
                        if($(CLO[sBulletId].div).is(":visible"))
                        {
                            continue;
                        }
                        CLO[sBulletId].Show();
                        if(CLO[sBulletId].tranin!=null)
                        {
                            iDur = 1000*CLO[sBulletId].tranin.duration;
                            if(isNaN(iDur))
                            {
                                iDur = 100;
                            }
                            oCurObj.data.iDisplayTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Display" }); }, iDur);
                        }
                        return false;
                    }
                }
            }
            oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "activate" ] } } );
            oCurObj.CallMethod({ sMethod: "CheckInit" } );
            if(oCurObj.jxParams.children("q_submit_type").text()=="button")
            {
                oCurObj.CallMethod({ sMethod: "Button", oMethodArgs: { sAction: "disable" } });
            }
            break;
        }
        case "continue":
        case "browse":
        {
            if(oCurObj.data.bDisplayQText)
            {
                if(oCurObj.data.sQTextId!=null && oCurObj.data.sQTextId!="")
                {
                    if(CLO[oCurObj.data.sQTextId]!=null)
                    {
                        if(!$(CLO[oCurObj.data.sQTextId].div).is(":visible"))
                        {
                            CLO[oCurObj.data.sQTextId].Show({ bActionCall: true, bUseTransition: false });
                        }
                    }
                }
            }
            if(oCurObj.data.bDisplayInstruction)
            {
                if(oCurObj.data.sInstrId!=null && oCurObj.data.sInstrId!="")
                {
                    if(CLO[oCurObj.data.sInstrId]!=null)
                    {
                        if(!$(CLO[oCurObj.data.sInstrId].div).is(":visible"))
                        {
                            CLO[oCurObj.data.sInstrId].Show({ bActionCall: true, bUseTransition: false });
                        }
                    }
                }
            }
            for(var i=0; i<oCurObj.data.aTargets.length; i++)
            {
                if(oCurObj.data.aTargets[i]=="")
                {
                    continue;
                }
                if(typeof oCurObj.data.aTargets[i] == "string")
                {
                    if($(CLO[ oCurObj.data.aTargets[i] ].div).is(":visible"))
                    {
                        continue;
                    }
                    CLO[ oCurObj.data.aTargets[i] ].Show({ bActionCall: true, bUseTransition: false });
                }
                else if(typeof oCurObj.data.aTargets[i] == "object")
                {
                    for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                    {
                        if($(CLO[ oCurObj.data.aTargets[i][j] ].div).is(":visible"))
                        {
                            continue;
                        }
                        CLO[ oCurObj.data.aTargets[i][j] ].Show({ bActionCall: true, bUseTransition: false });
                    }
                }
            }
            var aAllResponses = [];
            for(var i=0; i<CLZ.oStore[sQuestionId].R.length; i++)
            {
                for(var j=0; j<CLZ.oStore[sQuestionId].R[i].length; j++)
                {
                    if(CLZ.oStore[sQuestionId].R[i][j]!=null && CLZ.oStore[sQuestionId].R[i][j]!="") aAllResponses.push(CLZ.oStore[sQuestionId].R[i][j]);
                }
            }
            var bStop = false;
            var sBulletCode;
            for(var i=0; i<CLZ.oStore[sQuestionId].O.length; i++)
            {
                sBulletCode = CLZ.oStore[sQuestionId].O[i];
                if(oCurObj.data.sDisplayOrder=="seq")
                {
                    if($.inArray(sBulletCode, aAllResponses)==-1)
                    {
                        bStop = true;
                    }
                }
                sBulletId = oCurObj.data.oBullets[sBulletCode].sId;
                if(sBulletId=="") continue;
                if($(CLO[sBulletId].div).is(":visible")) continue;
                CLO[sBulletId].Show({ bActionCall: true, bUseTransition: false });
                if(bStop) break;
            }
            oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "activate" ] } } );
            for(var i=0; i<oCurObj.data.aTargets.length; i++)
            {
                if(typeof oCurObj.data.aTargets[i] == "string")
                {
                    for(var j=0; j<CLZ.oStore[sQuestionId].R[i].length; j++)
                    {
                        if(CLZ.oStore[sQuestionId].R[i][j]!=null)
                        {
                            oCurObj.CallMethod({ sMethod: "Place", oMethodArgs: { sTargetId: oCurObj.data.aTargets[i], sBulletId: oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].R[i][j] ].sId } });
                        }
                    }
                }
                else if(typeof oCurObj.data.aTargets[i] == "object")
                {
                    for(var j=0; j<oCurObj.data.aTargets[i].length; j++)
                    {
                        if(CLZ.oStore[sQuestionId].R[i][j]!=null && CLZ.oStore[sQuestionId].R[i][j]!="")
                        {
                            oCurObj.CallMethod({ sMethod: "Place", oMethodArgs: { sTargetId: oCurObj.data.aTargets[i][j], sBulletId: oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].R[i][j] ].sId } });
                        }
                    }
                }
            }
            if(oCurObj.data.sMode=="browse")
            {
                oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "deactivate" ] } } );
                if(oCurObj.jxParams.children("q_submit_type").text()=="button")
                {
                    oCurObj.CallMethod({ sMethod: "Button", oMethodArgs: { sAction: "hide" } });
                }
            }
            else
            {
                if(oCurObj.jxParams.children("q_submit_type").text()=="button" && aAllResponses.length==oCurObj.data.iTotalElems)
                {
                    oCurObj.CallMethod({ sMethod: "Button", oMethodArgs: { sAction: "show" } });
                }
            }
        }
    }
    return true;
}

function Snap(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var jTarget = $("#" + argobj.sDropId);
    var jBullet = $("#" + argobj.sDragId);
    var sBulletCode = jBullet.attr("data-vq-drag");
    var iDropCode = +jTarget.attr("data-vq-drop") - 1; // to address array
    var oReplaced = {};
    var oBullet =
    {
        iH: jBullet.outerHeight(),
        iL: jBullet.position().left/CLZ.nZoom,
        iT: jBullet.position().top/CLZ.nZoom,
        iW: jBullet.outerWidth()
    };
    var oTarget =
    {
        iH: jTarget.height(),
        iL: jTarget.position().left/CLZ.nZoom,
        iT: jTarget.position().top/CLZ.nZoom,
        iW: jTarget.width()
    };
    var iLeft = oTarget.iL;
    var iTop = oTarget.iT;
    if(typeof oCurObj.data.aTargets[iDropCode] == "string")
    {
        var jxVar = $(oCurObj.data.jxVars[iDropCode]);
        var iInterElem = +jxVar.children("interelem").text();
        var iMax = +jxVar.children("max_qty").text();
        if(iMax>0 && CLZ.oStore[sQuestionId].R[iDropCode].length>=iMax)
        {
            if(oCurObj.data.bReplace)
            {
                // dude, get lost!
                var sInnerId = (oCurObj.jxParams.children("if_busy").text()=="replace_first") ? CLZ.oStore[sQuestionId].R[iDropCode].shift() : CLZ.oStore[sQuestionId].R[iDropCode].pop();
                var sFreeId = oCurObj.data.oBullets[sInnerId].sId;
                $("#" + sFreeId).css({ "left": CLO[sFreeId].initial.x + "px", "top": CLO[sFreeId].initial.y + "px" });
                CLO[sFreeId].current.x = CLO[sFreeId].initial.x;
                CLO[sFreeId].current.y = CLO[sFreeId].initial.y;
                oReplaced = { sInner: sInnerId, sId: sFreeId };
            }
            else
            {
                // busy, go back
                jBullet.css({ "left": CLO[argobj.sDragId].current.x + "px", "top": CLO[argobj.sDragId].current.y + "px" });
                return false;
            }
        }
        if($.inArray(sBulletCode, CLZ.oStore[sQuestionId].R[iDropCode])==-1)
        {
            CLZ.oStore[sQuestionId].R[iDropCode].push(sBulletCode);
            if(oCurObj.data.sSnap=="none")
            {
                CLO[argobj.sDragId].current.x = oBullet.iL;
                CLO[argobj.sDragId].current.y = oBullet.iT;
                CLO[argobj.sDragId].oStates["default"].current.x = CLO[argobj.sDragId].current.x;
                CLO[argobj.sDragId].oStates["default"].current.y = CLO[argobj.sDragId].current.y;
                if(CLO[argobj.sDragId].oStates["highlighted"]!=null)
                {
                    CLO[argobj.sDragId].oStates["highlighted"].current.x = CLO[argobj.sDragId].current.x;
                    CLO[argobj.sDragId].oStates["highlighted"].current.y = CLO[argobj.sDragId].current.y;
                }
            }
            else
            {
                var iQty = CLZ.oStore[sQuestionId].R[iDropCode].length;
                var iTotalW = 0;
                var iTotalH = 0;
                var oElems = {};
                var jElem;
                for(var i=0; i<CLZ.oStore[sQuestionId].R[iDropCode].length; i++)
                {
                    oElems[CLZ.oStore[sQuestionId].R[iDropCode][i]] = $(".cl-object[data-frame-id='" + CLZ.sCurrentFrameId + "'][data-vq-drag='" + CLZ.oStore[sQuestionId].R[iDropCode][i] + "']");
                    jElem = oElems[CLZ.oStore[sQuestionId].R[iDropCode][i]];
                    iTotalW += jElem.width();
                    iTotalH += jElem.height();
                }
                iTotalW += (CLZ.oStore[sQuestionId].R[iDropCode].length-1)*iInterElem;
                iTotalH += (CLZ.oStore[sQuestionId].R[iDropCode].length-1)*iInterElem;
                var iNewL = (oCurObj.data.sSnap=="mc") ? (0.5*(oTarget.iW - iTotalW)) : ((oCurObj.data.sSnap=="mr") ? oTarget.iW : 0);
                var iFinalL = 0;
                for(var i=0; i<CLZ.oStore[sQuestionId].R[iDropCode].length; i++)
                {
                    jElem = oElems[CLZ.oStore[sQuestionId].R[iDropCode][i]];
                    switch(oCurObj.data.sSnap)
                    {
                        case "ct":
                        case "cm":
                        case "cb":
                        {
                            iFinalL = 0.5*(oTarget.iW - jElem.outerWidth());
                            break;
                        }
                        case "mc":
                        case "ml":
                        {
                            iFinalL = iNewL;
                            iNewL += jElem.outerWidth() + iInterElem;
                            break;
                        }
                        case "mr":
                        {
                            iFinalL = iNewL - jElem.outerWidth();
                            iNewL = iFinalL - iInterElem;
                            break;
                        }
                    }
                    CLO[jElem.attr("id")].current.x = (iLeft + iFinalL);
                    CLO[jElem.attr("id")].oStates["default"].current.x = CLO[jElem.attr("id")].current.x;
                    if(CLO[jElem.attr("id")].oStates["highlighted"]!=null)
                    {
                        CLO[jElem.attr("id")].oStates["highlighted"].current.x = CLO[jElem.attr("id")].current.x;
                    }
                    jElem.css({ "left": CLO[jElem.attr("id")].current.x + "px" });
                }
                var iNewT = (oCurObj.data.sSnap=="cm") ? (0.5*(oTarget.iH - iTotalH)) : ((oCurObj.data.sSnap=="cb") ? oTarget.iH : 0);
                var iFinalT = 0;
                for(var i=0; i<CLZ.oStore[sQuestionId].R[iDropCode].length; i++)
                {
                    jElem = oElems[CLZ.oStore[sQuestionId].R[iDropCode][i]];
                    switch(oCurObj.data.sSnap)
                    {
                        case "ml":
                        case "mc":
                        case "mr":
                        {
                            iFinalT = 0.5*(oTarget.iH - jElem.outerHeight());
                            break;
                        }
                        case "ct":
                        case "cm":
                        {
                            iFinalT = iNewT;
                            iNewT += jElem.outerHeight() + iInterElem;
                            break;
                        }
                        case "cb":
                        {
                            iFinalT = iNewT - jElem.outerHeight();
                            iNewT = iFinalT - iInterElem;
                            break;
                        }
                    }
                    CLO[jElem.attr("id")].current.y = (iTop + iFinalT);
                    CLO[jElem.attr("id")].oStates["default"].current.y = CLO[jElem.attr("id")].current.y;
                    if(CLO[jElem.attr("id")].oStates["highlighted"]!=null)
                    {
                        CLO[jElem.attr("id")].oStates["highlighted"].current.y = CLO[jElem.attr("id")].current.y;
                    }
                    jElem.css({ "top": CLO[jElem.attr("id")].current.y + "px" });
                }
            }
        }
    }
    else if(typeof oCurObj.data.aTargets[iDropCode] == "object")
    {
        var iTargetNum = $.inArray(argobj.sDropId, oCurObj.data.aTargets[iDropCode]);
        if(iTargetNum==-1 || CLZ.oStore[sQuestionId].R[iDropCode][iTargetNum]!="")
        {
            if(oCurObj.data.bReplace)
            {
                // dude, get lost!
                var sIdToReplace = oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].R[iDropCode][iTargetNum] ].sId;
                $("#" + sIdToReplace).css({ "left": CLO[sIdToReplace].initial.x + "px", "top": CLO[sIdToReplace].initial.y + "px" });
                CLO[sIdToReplace].current.x = CLO[sIdToReplace].initial.x;
                CLO[sIdToReplace].current.y = CLO[sIdToReplace].initial.y;
                oReplaced = { sInner: CLZ.oStore[sQuestionId].R[iDropCode][iTargetNum], sId: sIdToReplace };
                CLZ.oStore[sQuestionId].R[iDropCode][iTargetNum] = "";
            }
            else
            {
                // busy, go back
                jBullet.css({ "left": CLO[argobj.sDragId].current.x + "px", "top": CLO[argobj.sDragId].current.y + "px" });
                return false;
            }
        }
        CLZ.oStore[sQuestionId].R[iDropCode][iTargetNum] = sBulletCode;
        if(oCurObj.data.sSnap=="none")
        {
            CLO[argobj.sDragId].current.x = oBullet.iL;
            CLO[argobj.sDragId].current.y = oBullet.iT;
        }
        else
        {
            switch(oCurObj.data.sSnap)
            {
                case "ct":
                case "cm":
                case "cb":
                case "mc":
                {
                    iLeft += (0.5*(oTarget.iW - oBullet.iW));
                    break;
                }
                case "mr":
                {
                    iLeft += (oTarget.iW - oBullet.iW);
                    break;
                }
            }
            switch(oCurObj.data.sSnap)
            {
                case "ml":
                case "mc":
                case "mr":
                case "cm":
                {
                    iTop += 0.5*(oTarget.iH - oBullet.iH);
                    break;
                }
                case "cb":
                {
                    iTop += oTarget.iH - oBullet.iH;
                    break;
                }
            }
            CLO[argobj.sDragId].current.x = iLeft;
            CLO[argobj.sDragId].current.y = iTop;
            jBullet.css({ "left": iLeft + "px", "top": iTop + "px" });
        }
    }
    var iSet = 0;
    for(var i=0; i<CLZ.oStore[sQuestionId].R.length; i++)
    {
        if(CLZ.oStore[sQuestionId].R[i].length==0)
        {
            continue;
        }
        for(var j=0; j<CLZ.oStore[sQuestionId].R[i].length; j++)
        {
            if(CLZ.oStore[sQuestionId].R[i][j]!="")
            {
                iSet++;
            }
        }
    }
    if(iSet==oCurObj.data.iTotalElems)
    {
        oCurObj.FireEvent({ sName: "onAllInPlace" });
        if(oCurObj.data.sSubmitType=="button")
        {
            oCurObj.CallMethod({ sMethod: "Button", oMethodArgs: { sAction: "show" } });
        }
        else if(oCurObj.data.sSubmitType=="done")
        {
            oCurObj.CallMethod({ sMethod: "Submit" });
        }
    }
    else if(oCurObj.data.sDisplayOrder=="seq")
    {
        if(oReplaced.sId==null)
        {
            for(var i=0; i<CLZ.oStore[sQuestionId].O.length; i++)
            {
                if($("#" + oCurObj.data.oBullets[CLZ.oStore[sQuestionId].O[i]].sId).is(":visible")) continue;
                CLO[oCurObj.data.oBullets[CLZ.oStore[sQuestionId].O[i]].sId].Show();
                break;
            }
        }
    }
    return true;
}

function UIEvent(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var jElem = $(argobj.elem);
    if(jElem.attr("data-vq-type")=="btn")
    {
        var sBtnIdle = oCurObj.jxParams.children("q_submit_idle").text();
        var sBtnOver = oCurObj.jxParams.children("q_submit_over").text();
        var sBtnDisabled = oCurObj.jxParams.children("q_submit_disabled").text();
        switch(argobj.evt.type)
        {
            case "mouseover":
            {
                if(sBtnOver!=sBtnIdle && CLO[sBtnOver]!=null && CLO[sBtnIdle]!=null)
                {
                    CLO[sBtnIdle].Hide({ bActionCall: true, bUseTransition: false });
                    CLO[sBtnOver].Show({ bActionCall: true, bUseTransition: false });
                }
                break;
            }
            case "mouseout":
            {
                if(sBtnOver!=sBtnIdle && CLO[sBtnOver]!=null && CLO[sBtnIdle]!=null)
                {
                    if(CLZ.bSoundOn && oCurObj.data.sSoundOver!="none")
                    {
                        CL.Sound.CLStop({ jPlayer: oCurObj.data.jAudioOver });
                    }
                    if($(CLO[sBtnOver].div).is(":visible"))
                    {
                        CLO[sBtnOver].Hide({ bActionCall: true, bUseTransition: false });
                        CLO[sBtnIdle].Show({ bActionCall: true, bUseTransition: false });
                    }
                }
                break;
            }
            case "click":
            {
                if(CLZ.bSoundOn && oCurObj.data.sSoundClick!="none")
                {
                    CL.Sound.CLPlay({ jPlayer: oCurObj.data.jAudioClick });
                }
                oCurObj.CallMethod({ sMethod: "Button", oMethodArgs: { sAction: "hide" } });
                oCurObj.CallMethod({ sMethod: "Submit" });
                break;
            }
        }
    }
    return true;
}

function Feedback(argobj)
{
    var oCurObj = CLO[argobj.pid];
    if(oCurObj==null) return false;
    if(!oCurObj.data.bFeedback) return false;
    clearTimeout(oCurObj.data.iFBTimer);

    var sCorId = oCurObj.jxParams.children("q_fb_correct").text();
    var sIncId = oCurObj.jxParams.children("q_fb_incorrect_common").text();
    if(oCurObj.data.bFeedbackCorrect)
    {
        if(sCorId!=null && sCorId!="")
        {
            var jxGroup = CL.jxGroups.find("group[id='" + sCorId + "']");
            var aTargets = [];
            if(jxGroup.length!=0)
            {
                jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
            }
            else
            {
                aTargets.push(sCorId);
            }
            for(var i=0; i<aTargets.length; i++)
            {
                if(CLO[aTargets[i]]!=null)
                {
                    if($(CLO[aTargets[i]].div).is(":visible"))
                    {
                        CLO[aTargets[i]].Hide({ bActionCall: true, bUseTransition: false });
                    }
                }
            }
        }
    }
    if(oCurObj.data.bFeedbackIncorrect)
    {
        switch(oCurObj.data.sFeedbackIncorrect)
        {
            case "byatt":
            {
                oCurObj.jxParams.find("q_fb_incorrect_by_attempt > item").each(function ()
                {
                    var sId = $(this).children("q_fb_incorrect_by_att").text();
                    if(sId!=null && sId!="")
                    {
                        var jxGroup = CL.jxGroups.find("group[id='" + sId + "']");
                        var aTargets = [];
                        if(jxGroup.length!=0)
                        {
                            jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
                        }
                        else
                        {
                            aTargets.push(sId);
                        }
                        for(var i=0; i<aTargets.length; i++)
                        {
                            if(CLO[aTargets[i]]!=null)
                            {
                                if($(CLO[aTargets[i]].div).is(":visible"))
                                {
                                    CLO[aTargets[i]].Hide({ bActionCall: true, bUseTransition: false });
                                }
                            }
                        }
                    }
                });
                break;
            }
            case "common":
            {
                if(sIncId!=null && sIncId!="")
                {
                    var jxGroup = CL.jxGroups.find("group[id='" + sIncId + "']");
                    var aTargets = [];
                    if(jxGroup.length!=0)
                    {
                        jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
                    }
                    else
                    {
                        aTargets.push(sIncId);
                    }
                    for(var i=0; i<aTargets.length; i++)
                    {
                        if(CLO[aTargets[i]]!=null)
                        {
                            if($(CLO[aTargets[i]].div).is(":visible"))
                            {
                                CLO[aTargets[i]].Hide({ bActionCall: true, bUseTransition: false });
                            }
                        }
                    }
                }
                break;
            }
        }
    }
    if(argobj.sReason==null)
    {
        return true;
    }
    switch(argobj.sReason)
    {
        case "correct":
        {
            if(oCurObj.data.bFeedbackCorrect)
            {
                if(sCorId!=null && sCorId!="")
                {
                    var jxGroup = CL.jxGroups.find("group[id='" + sCorId + "']");
                    var aTargets = [];
                    if(jxGroup.length!=0)
                    {
                        jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
                    }
                    else
                    {
                        aTargets.push(sCorId);
                    }
                    for(var i=0; i<aTargets.length; i++)
                    {
                        if(CLO[aTargets[i]]!=null)
                        {
                            if(!$(CLO[aTargets[i]].div).is(":visible"))
                            {
                                CLO[aTargets[i]].Show();
                            }
                        }
                    }
                }
                if(oCurObj.data.bFeedbackTimer)
                {
                    oCurObj.data.iFBTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Feedback" }); }, oCurObj.data.iHideFBIn);
                }
            }
            break;
        }
        case "incorrect":
        {
            if(oCurObj.data.bFeedbackIncorrect)
            {
                switch(oCurObj.data.sFeedbackIncorrect)
                {
                    case "common":
                    {
                        if(sIncId!=null && sIncId!="")
                        {
                            var jxGroup = CL.jxGroups.find("group[id='" + sIncId + "']");
                            var aTargets = [];
                            if(jxGroup.length!=0)
                            {
                                jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
                            }
                            else
                            {
                                aTargets.push(sIncId);
                            }
                            for(var i=0; i<aTargets.length; i++)
                            {
                                if(CLO[aTargets[i]]!=null)
                                {
                                    if(!$(CLO[aTargets[i]].div).is(":visible"))
                                    {
                                        CLO[aTargets[i]].Show();
                                    }
                                }
                            }
                        }
                        break;
                    }
                    case "byatt":
                    {
                        var iAtt = -1;
                        for(var j=0; j<CLZ.oStore[argobj.pid].A.length; j++)
                        {
                            if(CLZ.oStore[argobj.pid].A[j].u!="c")
                            {
                                iAtt = j - 1;
                                break;
                            }
                        }
                        if(iAtt==-1) iAtt = CLZ.oStore[argobj.pid].A.length - 1;
                        if(iAtt==-1) return false;
                        var jxFB = oCurObj.jxParams.find("q_fb_incorrect_by_attempt > item");
                        if(jxFB.length<iAtt+1) return false;
                        sIncId = $(jxFB[iAtt]).children("q_fb_incorrect_by_att").text();
                        if(sIncId!=null && sIncId!="")
                        {
                            var jxGroup = CL.jxGroups.find("group[id='" + sIncId + "']");
                            var aTargets = [];
                            if(jxGroup.length!=0)
                            {
                                jxGroup.children("ref").each(function () { aTargets.push($(this).attr("id")) });
                            }
                            else
                            {
                                aTargets.push(sIncId);
                            }
                            for(var i=0; i<aTargets.length; i++)
                            {
                                if(CLO[aTargets[i]]!=null)
                                {
                                    if(!$(CLO[aTargets[i]].div).is(":visible"))
                                    {
                                        CLO[aTargets[i]].Show();
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
                if(oCurObj.data.bFeedbackTimer)
                {
                    oCurObj.data.iFBTimer = setTimeout(function () { oCurObj.CallMethod({ sMethod: "Feedback" }); }, oCurObj.data.iHideFBIn);
                }
            }
            break;
        }
    }
    return true;
}

function Submit(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    oCurObj.FireEvent({ sName: "onAttempt" });
    var bCorrect = false;
    var iCurrentTime = (new Date()).valueOf();
    var iAttemptIdx = -1;
    for(var i=0; i<CLZ.oStore[sQuestionId].A.length; i++)
    {
        if(CLZ.oStore[sQuestionId].A[i].u=="c") continue;
        iAttemptIdx = i;
        break;
    }
    if(iAttemptIdx==-1) return false; // extra fuse
    var nScore = 0;
    switch(oCurObj.data.sType)
    {
        case "otm":
        {
            switch(oCurObj.data.sScoringType)
            {
                case "plain":
                case "regressive":
                case "byobj":
                {
                    if(CLZ.oStore[sQuestionId].R.length==CLZ.oStore[sQuestionId].P.length)
                    {
                        bCorrect = true;
                        _main_loop:
                        for(var i=0; i<CLZ.oStore[sQuestionId].P.length; i++)
                        {
                            if(typeof oCurObj.data.aTargets[i] == "string")
                            {
                                if(CLZ.oStore[sQuestionId].P[i].length!=CLZ.oStore[sQuestionId].R[i].length)
                                {
                                    bCorrect = false;
                                    break _main_loop;
                                }
                                for(var j=0; j<CLZ.oStore[sQuestionId].P[i].length; j++)
                                {
                                    if($.inArray( CLZ.oStore[sQuestionId].R[i][j], CLZ.oStore[sQuestionId].P[i])==-1)
                                    {
                                        bCorrect = false;
                                        break _main_loop;
                                    }
                                }
                            }
                            else if(typeof oCurObj.data.aTargets[i] == "object")
                            {
                                var iCnt = 0;
                                for(var j=0; j<CLZ.oStore[sQuestionId].R[i].length; j++)
                                {
                                    if(CLZ.oStore[sQuestionId].R[i][j]=="")
                                    {
                                        continue;
                                    }
                                    iCnt++;
                                    if($.inArray( CLZ.oStore[sQuestionId].R[i][j], CLZ.oStore[sQuestionId].P[i])==-1)
                                    {
                                        bCorrect = false;
                                        break _main_loop;
                                    }
                                }
                                if(CLZ.oStore[sQuestionId].P[i].length!=iCnt)
                                {
                                    bCorrect = false;
                                    break _main_loop;
                                }
                            }
                        }
                    }
                    oCurObj.CallMethod({ sMethod: "CloseAttempt", oMethodArgs: { bInitNext: !bCorrect } });
                    if(oCurObj.data.bFeedback)
                    {
                        oCurObj.CallMethod({ sMethod: "Feedback", oMethodArgs: { sReason: (bCorrect ? "correct" : "incorrect") } });
                    }
                    if(bCorrect)
                    {
                        if(CLZ.bSoundOn && oCurObj.data.sSoundSuccess!="none")
                        {
                            CL.Sound.CLPlay({ jPlayer: oCurObj.data.jAudioSuccess });
                        }
                        oCurObj.FireEvent({ sName: "onSuccess" });
                        if(oCurObj.data.bShowCorrect)
                        {
                            oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "correct" ] } } );
                        }
                        if(oCurObj.data.bCredit)
                        {
                            switch(oCurObj.data.sScoringType)
                            {
                                case "plain":
                                {
                                    nScore = oCurObj.data.nBaseScore;
                                    for(var i=0; i<oCurObj.data.jxObjectives.length; i++)
                                    {
                                        CL.SCO.SetObjectiveScore({ sId: $(oCurObj.data.jxObjectives[i]).children("q_board").text(), sSrcId: sQuestionId, bReplace: true, nScore: nScore });
                                    }
                                    break;
                                }
                                case "regressive":
                                {
                                    nScore = oCurObj.data.nBaseScore*(CLZ.oStore[sQuestionId].A.length - iAttemptIdx);
                                    for(var i=0; i<oCurObj.data.jxObjectives.length; i++)
                                    {
                                        CL.SCO.SetObjectiveScore({ sId: $(oCurObj.data.jxObjectives[i]).children("q_board").text(), sSrcId: sQuestionId, bReplace: true, nScore: nScore });
                                    }
                                    break;
                                }
                                case "byobj":
                                {
                                    for(var i=0; i<oCurObj.data.jxObjectives.length; i++)
                                    {
                                        nScore = +$(oCurObj.data.jxObjectives[i]).children("q_weight_byobj").text();
                                        CL.SCO.SetObjectiveScore({ sId: $(oCurObj.data.jxObjectives[i]).children("q_board").text(), sSrcId: sQuestionId, bReplace: true, nScore: nScore });
                                    }
                                    break;
                                }
                            }
                        }
                        oCurObj.CallMethod({ sMethod: "CloseQuestion" });
                    }
                    else
                    {
                        if(CLZ.bSoundOn && oCurObj.data.sSoundFailure!="none")
                        {
                            CL.Sound.CLPlay({ jPlayer: oCurObj.data.jAudioFailure });
                        }
                        oCurObj.FireEvent({ sName: "onFailure" });
                        if(oCurObj.data.bNoMoreAttempts)
                        {
                            if(oCurObj.data.bShowCorrect)
                            {
                                oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "correct" ] } } );
                            }
                            if(oCurObj.data.bCredit)
                            {
                                nScore = 0;
                                for(var i=0; i<oCurObj.data.jxObjectives.length; i++)
                                {
                                    CL.SCO.SetObjectiveScore({ sId: $(oCurObj.data.jxObjectives[i]).children("q_board").text(), sSrcId: sQuestionId, bReplace: true, nScore: nScore });
                                }
                            }
                            oCurObj.CallMethod({ sMethod: "CloseQuestion" });
                        }
                    }
                    break;
                }
                case "sum":
                case "avg":
                case "max":
                case "min":
                {
                    oCurObj.CallMethod({ sMethod: "CloseAttempt", oMethodArgs: { bInitNext: false } });
                    if(oCurObj.data.bCredit)
                    {
                        var nSum = 0;
                        var nMax = -99999;
                        var nMin = 99999;
                        for(var i=0; i<CLZ.oStore[sQuestionId].R.length; i++)
                        {
                            for(var j=0; j<CLZ.oStore[sQuestionId].R[i].length; j++)
                            {
                                var iIdx = $.inArray( CLZ.oStore[sQuestionId].R[i][j], CLZ.oStore[sQuestionId].P[i]);
                                if(iIdx!=-1)
                                {
                                    var aParts = CLZ.oStore[sQuestionId].R[i][j].split("b");
                                    var jxBullet = $(oCurObj.data.jxVars[+CLZ.oStore[sQuestionId].R[i]-1]).find("bullets > item")[+aParts[1]-1];
                                    nScore = +jxBullet.children("q_weight_by_var").text();
                                    nSum += nScore;
                                    if(nMax<nScore) nMax = nScore;
                                    if(nMin>nScore) nMin = nScore;
                                }
                            }
                        }
                        switch(oCurObj.data.sScoringType)
                        {
                            case "sum":
                            {
                                nScore = nSum;
                                break;
                            }
                            case "avg":
                            {
                                nScore = nSum/CLZ.oStore[sQuestionId].R.length;
                                break;
                            }
                            case "max":
                            {
                                nScore = nMax;
                                break;
                            }
                            case "min":
                            {
                                nScore = nMin;
                                break;
                            }
                        }
                        for(var i=0; i<oCurObj.data.jxObjectives.length; i++)
                        {
                            CL.SCO.SetObjectiveScore({ sId: $(oCurObj.data.jxObjectives[i]).children("q_board").text(), sSrcId: sQuestionId, bReplace: true, nScore: nScore });
                        }
                    }
                    oCurObj.CallMethod({ sMethod: "CloseQuestion" });
                    break;
                }
            }
            break;
        }
    }
    return true;
}

function Button(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sBtnIdle = oCurObj.jxParams.children("q_submit_idle").text();
    var sBtnOver = oCurObj.jxParams.children("q_submit_over").text();
    var sBtnDisabled = oCurObj.jxParams.children("q_submit_disabled").text();
    if(!oCurObj.data.bBtnReady)
    {
        if(oCurObj.data.bUseBtnState)
        {
            if(sBtnIdle!=null && sBtnIdle!="")
            {
                if(CLO[sBtnIdle]!=null)
                {
                    for(var sState in CLO[sBtnIdle].oStates)
                    {
                        if(sState=="default" || sState=="highlighted" || sState=="active")
                    {
                            $(CLO[sBtnIdle].oStates[sState].div).attr({ "data-vq-id": argobj.pid, "data-vq-type": "btn", "data-vq-role": "idle", "data-vq-idle-id": sBtnIdle }).addClass("cl-clickable unselectable").on("click", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) });
                        }
                    }
                }
            }
        }
        else
        {
            if(sBtnIdle!=null && sBtnIdle!="")
            {
                if(CLO[sBtnIdle]!=null)
                {
                    $(CLO[sBtnIdle].div).attr({ "data-vq-id": argobj.pid, "data-vq-type": "btn", "data-vq-role": "idle", "data-vq-idle-id": sBtnIdle }).addClass("cl-clickable unselectable").on("click", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) });
                }
            }
            if(!CL.bTouch && sBtnOver!="")
            {
                if(sBtnOver!=null && sBtnOver!="")
                {
                    if(CLO[sBtnOver]!=null)
                    {
                        $(CLO[sBtnIdle].div).attr({ "data-vq-over-id": sBtnOver }).on("mouseover", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) }).on("mouseout", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) });
                        $(CLO[sBtnOver].div).attr({ "data-vq-id": argobj.pid, "data-vq-type": "btn", "data-vq-role": "over", "data-vq-idle-id": sBtnIdle, "data-vq-over-id": sBtnOver }).addClass("cl-clickable unselectable").on("mouseover", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) }).on("mouseout", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) }).on("click", function (e) { oCurObj.CallMethod({ sMethod: "UIEvent", oMethodArgs: { elem: this, evt: e }} ) });
                    }
                }
            }
        }
        oCurObj.data.bBtnReady = true;
    }
    switch(argobj.sAction)
    {
        case "show":
        {
            if(oCurObj.data.bUseBtnState)
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if(!$(CLO[sBtnIdle].div).is(":visible"))
                        {
                            CLO[sBtnIdle].Show();
                        }
                        CLO[sBtnIdle].SetState({ sState: "default" });
                    }
                }
            }
            else
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if(!$(CLO[sBtnIdle].div).is(":visible"))
                        {
                            CLO[sBtnIdle].Show();
                        }
                    }
                }
                if(sBtnOver!=null && sBtnOver!="")
                {
                    if(CLO[sBtnOver]!=null)
                    {
                        if($(CLO[sBtnOver].div).is(":visible"))
                        {
                            CLO[sBtnOver].Hide();
                        }
                    }
                }
                if(sBtnDisabled!=null && sBtnDisabled!="")
                {
                    if(CLO[sBtnDisabled]!=null)
                    {
                        if($(CLO[sBtnDisabled].div).is(":visible"))
                        {
                            CLO[sBtnDisabled].Hide();
                        }
                    }
                }
            }
            break;
        }
        case "hide":
        {
            if(oCurObj.data.bUseBtnState)
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if($(CLO[sBtnIdle].div).is(":visible"))
                        {
                            CLO[sBtnIdle].Hide();
                        }
                    }
                }
            }
            else
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if($(CLO[sBtnIdle].div).is(":visible"))
                        {
                            CLO[sBtnIdle].Hide();
                        }
                    }
                }
                if(sBtnOver!=null && sBtnOver!="")
                {
                    if(CLO[sBtnOver]!=null)
                    {
                        if($(CLO[sBtnOver].div).is(":visible"))
                        {
                            CLO[sBtnOver].Hide();
                        }
                    }
                }
                if(sBtnDisabled!=null && sBtnDisabled!="")
                {
                    if(CLO[sBtnDisabled]!=null)
                    {
                        if(!$(CLO[sBtnDisabled].div).is(":visible"))
                        {
                            CLO[sBtnDisabled].Show();
                        }
                    }
                }
            }
            break;
        }
        case "disable":
        {
            if(oCurObj.data.bUseBtnState)
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if(CLO[sBtnIdle].oStates["disabled"]!=null)
                        {
                        CLO[sBtnIdle].SetState({ sState: "disabled" });
                    }
                        else
                        {
                            CLO[sBtnIdle].Hide();
                        }
                    }
                }
            }
            else
            {
                if(sBtnIdle!=null && sBtnIdle!="")
                {
                    if(CLO[sBtnIdle]!=null)
                    {
                        if($(CLO[sBtnIdle].div).is(":visible"))
                        {
                            CLO[sBtnIdle].Hide();
                        }
                    }
                }
                if(sBtnOver!=null && sBtnOver!="")
                {
                    if(CLO[sBtnOver]!=null)
                    {
                        if($(CLO[sBtnOver].div).is(":visible"))
                        {
                            CLO[sBtnOver].Hide();
                        }
                    }
                }
                if(sBtnDisabled!=null && sBtnDisabled!="")
                {
                    if(CLO[sBtnDisabled]!=null)
                    {
                        if(!$(CLO[sBtnDisabled].div).is(":visible"))
                        {
                            CLO[sBtnDisabled].Show();
                        }
                    }
                }
            }
            break;
        }
    }
    return true;
}

function Manage(argobj)
{
    if(argobj.aActions==null) return false;
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var jxVar;
    var sTargetId;
    var sBulletId;
    var sCorId;
    var sIncId;
    var sDisId;
    var iTargetCnt;
    var jxBullet;
    for(var i=0; i<argobj.aActions.length; i++)
    {
        switch(argobj.aActions[i])
        {
            case "activate":
            {
                for(var j=0; j<oCurObj.data.aTargets.length; j++)
                {
                    iTargetCnt = j + 1;
                    if(oCurObj.data.aTargets[j]=="")
                    {
                        continue;
                    }
                    if(typeof oCurObj.data.aTargets[j] == "string")
                    {
                        $(CLO[ oCurObj.data.aTargets[j] ].div).addClass("cl-drop").attr({ "data-vq-drop": iTargetCnt }).droppable(
                        {
                            tolerance: "pointer",
                            scope: sQuestionId,
                            drop: function (event, ui)
                            {
                                if(ui.draggable.length!=0)
                                {
                                    CLO[sQuestionId].CallMethod({ sMethod: "Snap", oMethodArgs: { sDropId: $(this).attr("id"), sDragId: ui.draggable.attr("id") } });
                                }
                                return false;
                            }
                        });
                    }
                    else if(typeof oCurObj.data.aTargets[j] == "object")
                    {
                        for(var k=0; k<oCurObj.data.aTargets[j].length; k++)
                        {
                            $(CLO[ oCurObj.data.aTargets[j][k] ].div).addClass("cl-drop").attr({ "data-vq-drop": iTargetCnt }).droppable(
                            {
                                tolerance: "pointer",
                                scope: sQuestionId,
                                drop: function (event, ui)
                                {
                                    if(ui.draggable.length!=0)
                                    {
                                        CLO[sQuestionId].CallMethod({ sMethod: "Snap", oMethodArgs: { sDropId: $(this).attr("id"), sDragId: ui.draggable.attr("id") } });
                                    }
                                    return false;
                                }
                            });
                        }
                    }
                }
                var jBoard = $(CL.oBoard);
                var containmentWidth = 0;
                var containmentHeight = 0;

                for(var sKey in oCurObj.data.oBullets)
                {
                    jBulletDiv = $(CLO[ oCurObj.data.oBullets[sKey].sId ].div);
                    if(jBulletDiv.hasClass("ui-draggable"))
                    {
                        jBulletDiv.draggable("destroy");
                    }
                    jBulletDiv.attr({ "data-vq-drag": sKey }).addClass("cl-drag").draggable(
                    {
                        scope: sQuestionId,
                        zIndex: 4999,
                        start: function (event, ui)
                        {
                            containmentWidth = (jBoard.width() - ui.helper.width())*CLZ.nZoom;
                            containmentHeight = (jBoard.height() - ui.helper.height())*CLZ.nZoom;
                            var sDragCode = $(this).attr("data-vq-drag");
                            var iIdx = -1;
                            for(var i=0; i<CLZ.oStore[sQuestionId].R.length; i++)
                            {
                                iIdx = $.inArray(sDragCode, CLZ.oStore[sQuestionId].R[i]);
                                if(iIdx!=-1)
                                {
                                    if(typeof oCurObj.data.aTargets[i] == "string")
                                    {
                                        CLZ.oStore[sQuestionId].R[i].splice(iIdx,1);
                                    }
                                    else
                                    {
                                        CLZ.oStore[sQuestionId].R[i][iIdx] = "";
                                    }
                                    break;
                                }
                            }
                            oCurObj.CallMethod({ sMethod: "Feedback" });
                        },
                        drag: function (event, ui)
                        {
                             ui.position.left = Math.max(0, Math.min(ui.position.left, containmentWidth));
                             ui.position.top = Math.max(0, Math.min(ui.position.top, containmentHeight));
                        },
                        stop: function (event, ui)
                        {
                            var sDragId = $(this).attr("data-vq-drag");
                            var iIdx = -1;
                            for(var i=0; i<CLZ.oStore[sQuestionId].R.length; i++)
                            {
                                iIdx = $.inArray(sDragId, CLZ.oStore[sQuestionId].R[i]);
                                if(iIdx!=-1)
                                {
                                    var sId = $(this).attr("id");
                                    CLO[sId].current.x = $(this).position().left/CLZ.nZoom;
                                    CLO[sId].current.y = $(this).position().top/CLZ.nZoom;
                                    break;
                                }
                            }
                        }
                    });
                    CLO[ oCurObj.data.oBullets[sKey].sId ].current.bDraggable = true;
                }
                break;
            }
            case "deactivate":
            {
                for(var j=0; j<oCurObj.data.aTargets.length; j++)
                {
                    iTargetCnt = j + 1;
                    if(oCurObj.data.aTargets[j]=="")
                    {
                        continue;
                    }
                    if(typeof oCurObj.data.aTargets[j] == "string")
                    {
                        if(CLO[ oCurObj.data.aTargets[j] ]!=null)
                        {
                            if($(CLO[ oCurObj.data.aTargets[j] ].div).hasClass("cl-drop"))
                            {
                                $(CLO[ oCurObj.data.aTargets[j] ].div).removeClass("cl-drop").droppable("destroy");
                            }
                        }
                    }
                    else if(typeof oCurObj.data.aTargets[j] == "object")
                    {
                        for(var k=0; k<oCurObj.data.aTargets[j].length; k++)
                        {
                            if(CLO[ oCurObj.data.aTargets[j][k] ]!=null)
                            {
                                if($(CLO[ oCurObj.data.aTargets[j][k] ].div).hasClass("cl-drop"))
                                {
                                    $(CLO[ oCurObj.data.aTargets[j][k] ].div).removeClass("cl-drop").droppable("destroy");
                                }
                            }
                        }
                    }
                }
                for(var sKey in oCurObj.data.oBullets)
                {
                    if(CLO[ oCurObj.data.oBullets[sKey].sId ]!=null)
                    {
                        if($(CLO[ oCurObj.data.oBullets[sKey].sId ].div).hasClass("ui-draggable"))
                        {
                            $(CLO[ oCurObj.data.oBullets[sKey].sId ].div).removeClass("cl-drag").draggable("destroy");
                        }
                        CLO[ oCurObj.data.oBullets[sKey].sId ].current.bDraggable = false;
                    }
                }
                break;
            }
            case "disable":
            {
                for(var sKey in oCurObj.data.oBullets)
                {
                    if(oCurObj.data.sOnFinish=="disabled")
                    {
                        jxVar = $(oCurObj.data.jxVars[ oCurObj.data.oBullets[sKey].iT-1 ]);
                        jxBullet = $(jxVar.find("bullets > item")[ oCurObj.data.oBullets[sKey].iB-1 ]);
                        if(jxBullet.children("var_object_based").text()=="yes")
                        {
                            sDisId = jxBullet.children("q_var_disabled").text();
                            if(sDisId!="")
                            {
                                if(CLO[sDisId]!=null && CLO[ oCurObj.data.oBullets[sKey].sId ]!=null)
                                {
                                    $(CLO[sDisId].div).css({ "left": CLO[ oCurObj.data.oBullets[sKey].sId ].current.x + "px", "top": CLO[ oCurObj.data.oBullets[sKey].sId ].current.y + "px" });
                                    CLO[sDisId].current.x = CLO[ oCurObj.data.oBullets[sKey].sId ].current.x;
                                    CLO[sDisId].current.y = CLO[ oCurObj.data.oBullets[sKey].sId ].current.y;
                                    CLO[sDisId].Show({ bActionCall: true, bUseTransition: false });
                                }
                            }
                        }
                        else
                        {
                            if(CLO[oBullet.sId].oStates["disabled"]!=null)
                            {
                                CLO[oBullet.sId].SetState({ sState: "disabled" });
                                $(CLO[oBullet.sId].div).css({ "left": CLO[oBullet.sId].oStates["default"].current.x + "px", "top": CLO[oBullet.sId].oStates["default"].current.y + "px" })
                                CLO[oBullet.sId].oStates["disabled"].current.x = CLO[oBullet.sId].oStates["default"].current.x;
                                CLO[oBullet.sId].oStates["disabled"].current.y = CLO[oBullet.sId].oStates["default"].current.y;
                            }
                        }
                    }
                    else
                    {
                        $(CLO[ oCurObj.data.oBullets[sKey].sId ].div).css({ "opacity": 0.90 });
                        CLO[ oCurObj.data.oBullets[sKey].sId ].current.nOpacity = 0.90;
                    }
                }
                break;
            }
            case "correct":
            {
                switch(oCurObj.jxParams.children("final_action").text())
                {
                    case "none":
                    {
                        return false;
                    }
                    case "correct":
                    {
                        for(var j=0; j<CLZ.oStore[sQuestionId].P.length; j++)
                        {
                            for(var k=0; k<CLZ.oStore[sQuestionId].P[j].length; k++)
                            {
                                oCurObj.CallMethod({ sMethod: "Place", oMethodArgs: { sTargetCode: oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].P[j][k] ].iT, sBulletId: oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].P[j][k] ].sId } });
                            }
                        }
                        break;
                    }
                    case "mark":
                    case "replace":
                    {
                        var oBullet;
                        for(var j=0; j<CLZ.oStore[sQuestionId].R.length; j++)
                        {
                            for(var k=0; k<CLZ.oStore[sQuestionId].R[j].length; k++)
                            {
                                oBullet = oCurObj.data.oBullets[ CLZ.oStore[sQuestionId].R[j][k] ];
                                jxVar = $(oCurObj.data.jxVars[ oBullet.iT - 1 ]);
                                jxBullet = $(jxVar.find("bullets > item")[ oBullet.iB - 1 ]);
                                if($.inArray(CLZ.oStore[sQuestionId].R[j][k], CLZ.oStore[sQuestionId].P[j])==-1)
                                {
                                    if(jxBullet.children("var_object_based").text()=="yes")
                                    {
                                        sIncId = jxBullet.children("q_var_error").text();
                                        if(sIncId=="")
                                        {
                                            continue;
                                        }
                                        if(CLO[sIncId]!=null)
                                        {
                                            $(CLO[sIncId].div).css({ "left": CLO[ oBullet.sId ].current.x + "px", "top": CLO[ oBullet.sId ].current.y + "px" });
                                            CLO[sIncId].Show();
                                            CLO[sIncId].current.x = CLO[ oBullet.sId ].current.x;
                                            CLO[sIncId].current.y = CLO[ oBullet.sId ].current.y;
                                        }
                                    }
                                    else
                                    {
                                        if(CLO[oBullet.sId].oStates["incorrect"]!=null)
                                        {
                                            CLO[oBullet.sId].SetState({ sState: "incorrect" });
                                            $(CLO[oBullet.sId].div).css({ "left": CLO[oBullet.sId].oStates["default"].current.x + "px", "top": CLO[oBullet.sId].oStates["default"].current.y + "px" })
                                            CLO[oBullet.sId].oStates["incorrect"].current.x = CLO[oBullet.sId].oStates["default"].current.x;
                                            CLO[oBullet.sId].oStates["incorrect"].current.y = CLO[oBullet.sId].oStates["default"].current.y;
                                        }
                                    }
                                }
                                else
                                {
                                    if(jxBullet.children("var_object_based").text()=="yes")
                                    {
                                        sCorId = jxBullet.children("q_var_correct").text();
                                        if(sCorId=="")
                                        {
                                            continue;
                                        }
                                        if(CLO[sCorId]!=null)
                                        {
                                            $(CLO[sCorId].div).css({ "left": CLO[ oBullet.sId ].current.x + "px", "top": CLO[ oBullet.sId ].current.y + "px" });
                                            CLO[sCorId].Show();
                                            CLO[sCorId].current.x = CLO[ oBullet.sId ].current.x;
                                            CLO[sCorId].current.y = CLO[ oBullet.sId ].current.y;
                                        }
                                    }
                                    else
                                    {
                                        if(CLO[oBullet.sId].oStates["correct"]!=null)
                                        {
                                            CLO[oBullet.sId].SetState({ sState: "correct" });
                                            $(CLO[oBullet.sId].div).css({ "left": CLO[oBullet.sId].oStates["default"].current.x + "px", "top": CLO[oBullet.sId].oStates["default"].current.y + "px" });
                                            CLO[oBullet.sId].oStates["correct"].current.x = CLO[ oBullet.sId ].oStates["default"].current.x;
                                            CLO[oBullet.sId].oStates["correct"].current.y = CLO[ oBullet.sId ].oStates["default"].current.y;
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
                var sFinalId = oCurObj.jxParams.children("final_obj").text();
                if(sFinalId!="")
                {
                    if(CLO[sFinalId]!=null)
                    {
                        CLO[sFinalId].Show();
                    }
                }
                break;
            }
        }
    }
    return true;
}

function CloseAttempt(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    var iAttemptIdx = -1;
    for(var i=0; i<CLZ.oStore[sQuestionId].A.length; i++)
    {
        if(CLZ.oStore[sQuestionId].A[i].u=="c") continue;
        iAttemptIdx = i;
        break;
    }
    var iNow = (new Date()).valueOf();
    var iStart = CLZ.oStore[sQuestionId].A[iAttemptIdx].s;
    CLZ.oStore[sQuestionId].A[iAttemptIdx] =
    {
        R: CLZ.oStore[sQuestionId].R.slice(0),
        s: iStart,
        d: iNow - iStart - CLZ.oStore[sQuestionId].s,
        u: "c"
    }; // current attempt closed
    iAttemptIdx++;
    var iAttemptsLeft = CLZ.oStore[sQuestionId].A.length - iAttemptIdx;
    if(iAttemptsLeft<0) iAttemptsLeft = 0;
    if(iAttemptsLeft==0 || CLZ.oStore[sQuestionId].A[iAttemptIdx]==null)
    {
        oCurObj.data.bNoMoreAttempts = true;
        CLO[argobj.pid].FireEvent({ sName: "onAttemptsLimit" });
    }
    else
    {
        if(argobj.bInitNext)
        {
            CLZ.oStore[sQuestionId].A[iAttemptIdx] =
            {
                s: iNow - CLZ.oStore[sQuestionId].s,
                d: 0,
                u: "i"
            }
            if((CLZ.oStore[sQuestionId].A.length>1) && (iAttemptIdx==CLZ.oStore[sQuestionId].A.length-1))
            {
                oCurObj.data.bLastAttempt = true;
                oCurObj.FireEvent({ sName: "onLastAttemptStart" });
            }
        }
    }
    return true;
}

function CloseQuestion(argobj)
{
    var oCurObj = CLO[argobj.pid];
    var sQuestionId = argobj.pid;
    oCurObj.CallMethod({ sMethod: "Manage", oMethodArgs: { aActions: [ "deactivate", "disable" ] } } );
    CLZ.oStore[sQuestionId].d = (new Date()).valueOf() - CLZ.oStore[sQuestionId].s;
    CLZ.oStore[sQuestionId].u = "c";
    oCurObj.FireEvent({ sName: "onQuestionEnd" })
    return true;
}

function GetProperty(argobj)
{
    if(argobj.pid==null || argobj.property==null) return "";
    if(CLO[argobj.pid]==null) return "";
    switch(argobj.property.toLowerCase())
    {
        case "questionmode":
        {
            return ((CLO[argobj.pid].data.sMode=="browse") ? "review" : "normal");
        }
        case "questiontype":
        {
            return CLO[argobj.pid].data.sType;
        }
        case "itemquantity":
        {
            return CLO[argobj.pid].data.jxVars.length;
        }
        case "questionvalue":
        {
            return CLZ.oStore[argobj.pid].R.join(",");
        }
        case "attemptslast":
        {
            var iAttemptsLeft = 0;
            for(var i=0; i<CLZ.oStore[argobj.pid].A.length; i++)
            {
                if(CLZ.oStore[sQuestionId].A[i].u=="c") continue;
                iAttemptsLeft = CLZ.oStore[argobj.pid].A.length - i;
                break;
            }
            return iAttemptsLeft;
        }
        case "attemptstotal":
        {
            return CLZ.oStore[argobj.pid].A.length;
        }
    }
    return "";
}
